vector<ll> dijkstra(const vector<vector<Edge>> &g, int start) {
    const ll inf = 1LL << 60;
    vector<ll> dist(g.size(), inf);
    using State = pair<ll, int>;
    priority_queue<State, vector<State>, greater<State>> q;
    dist[start] = 0;
    q.push({0, start});
    while (!q.empty()) {
        auto [du, u] = q.top();
        q.pop();
        if (du != dist[u]) continue;
        for (auto [v, w] : g[u]) {
            if (du + w < dist[v]) {
                dist[v] = du + w;
                q.push({dist[v], v});
            }
        }
    }
    return dist;
}

