vector<char> seen(n);
vector<int> order;
for (int start = 0; start < n; ++start) {
    if (seen[start]) continue;
    vector<pair<int, int>> st{{start, 0}};
    seen[start] = true;
    while (!st.empty()) {
        int u = st.back().first;
        int edge = st.back().second;
        if (edge == int(g[u].size())) {
            order.push_back(u);
            st.pop_back();
            continue;
        }
        ++st.back().second;
        int v = g[u][edge];
        if (!seen[v]) {
            seen[v] = true;
            st.push_back({v, 0});
        }
    }
}

fill(seen.begin(), seen.end(), false);
ll ans = 0;
for (auto it = order.rbegin(); it != order.rend(); ++it) {
    int start = *it;
    if (seen[start]) continue;
