    seen[start] = true;
    ll size = 0;
    while (!st.empty()) {
        int u = st.back();
        st.pop_back();
        ++size;
        for (int v : rev[u]) {
            if (seen[v]) continue;
            seen[v] = true;
            st.push_back(v);
        }
    }
    ans += size * (size - 1) / 2;
}

